DELETE FROM Language_en_US WHERE Tag='TXT_KEY_CWC_GUIDE_LUNANETWORK' OR Tag GLOB 'TXT_KEY_CWC_GUIDE_LUNANETWORK_*';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_LUNANETWORK_CIV_HEADING_1','Playstyle and victory plan');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_LUNANETWORK_CIV_TEXT_1','Luna Network[NEWLINE]Wide expansion and construction tempo[NEWLINE]Science or Domination; flexible conventional victories[NEWLINE][NEWLINE]Turn a network of useful cities into a stream of completed orders. Discounts and completion refunds reward sustained development; Rapid Response helps newly trained forces reach the point of need.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_LUNANETWORK_CIV_HEADING_2','Opening priorities');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_LUNANETWORK_CIV_TEXT_2','Escort Packet Settlers toward defensible food and resource sites. Cheap Cache Nodes help new cities become productive research centres, but ordinary Happiness and maintenance still determine how many cities you can support.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_LUNANETWORK_CIV_HEADING_3','Develop the engine');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_LUNANETWORK_CIV_TEXT_3','Keep normal production queues moving through needed buildings and combat units. Time military completions before a deployment; purchases and free units do not create the same refund engine. Use roads and a reserve army to cover a wide border.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_LUNANETWORK_CIV_HEADING_4','Convert the advantage');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_LUNANETWORK_CIV_TEXT_4','Convert the developed network into research capacity or several coordinated production centres. Reinforce campaigns continuously instead of assuming the temporary movement promotion is a permanent combat bonus.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_LUNANETWORK_CIV_HEADING_5','Strengths');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_LUNANETWORK_CIV_TEXT_5','- Discounted settlement and early research infrastructure help establish more viable cities.[NEWLINE]- Many qualifying completions repeatedly feed the next order.[NEWLINE]- Fresh land and naval combat units have a short deployment advantage.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_LUNANETWORK_CIV_HEADING_6','Weaknesses and costs');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_LUNANETWORK_CIV_TEXT_6','- There is no built-in Happiness or growth solution for overexpansion.[NEWLINE]- Refunds require qualifying production completions rather than purchases or Wonders.[NEWLINE]- Rapid Response adds tempo, not a general strength advantage.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_LUNANETWORK_CIV_HEADING_7','How to play against this civilization');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_LUNANETWORK_CIV_TEXT_7','- Contest strong settlement sites and attack exposed new cities before their infrastructure pays back.[NEWLINE]- Force military spending and road defense across several approaches.[NEWLINE]- Survive the fresh-unit deployment window and fight with terrain or stronger units.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_LUNANETWORK_CIV_HEADING_8','Common mistakes');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_LUNANETWORK_CIV_TEXT_8','- Expanding faster than food, Gold and Happiness can support.[NEWLINE]- Expecting Packet Settlers, Wonders or purchases to generate military completion refunds.[NEWLINE]- Counting on Rapid Response after its short duration has expired.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_LUNANETWORK_CIV_HEADING_9','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_LUNANETWORK_CIV_TEXT_9','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]Sol Intellect: Early territorial tempo can deny a protected, uninterrupted builder the space and safety needed for a tall engine.[NEWLINE][NEWLINE]The Boundless City: Early settlement can contest valuable land before the Architect''s contiguous territory reaches it; a capital assault still requires real military preparation.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]The Urgal: A sharp early melee timing can punish a network whose newest cities have only economic investment.[NEWLINE][NEWLINE]Viltrum: Scattered mature cities offer Momentum opportunities if Luna''s reinforcement network cannot hold the front.');
