INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_LUNANETWORK_BACKGROUND','Turn a network of useful cities into a stream of completed orders. Discounts and completion refunds reward sustained development; Rapid Response helps newly trained forces reach the point of need.');
