INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_LUNANETWORK_LEADER_HEADING_2','Priorities and decisions');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_LUNANETWORK_LEADER_TEXT_2','Escort Packet Settlers toward defensible food and resource sites. Cheap Cache Nodes help new cities become productive research centres, but ordinary Happiness and maintenance still determine how many cities you can support.[NEWLINE][NEWLINE]Keep normal production queues moving through needed buildings and combat units. Time military completions before a deployment; purchases and free units do not create the same refund engine. Use roads and a reserve army to cover a wide border.[NEWLINE][NEWLINE]Convert the developed network into research capacity or several coordinated production centres. Reinforce campaigns continuously instead of assuming the temporary movement promotion is a permanent combat bonus.');
