INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_LUNANETWORK_LEADER_TEXT_3','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]Sol Intellect: Early territorial tempo can deny a protected, uninterrupted builder the space and safety needed for a tall engine.[NEWLINE][NEWLINE]The Boundless City: Early settlement can contest valuable land before the Architect''s contiguous territory reaches it; a capital assault still requires real military preparation.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]The Urgal: A sharp early melee timing can punish a network whose newest cities have only economic investment.[NEWLINE][NEWLINE]Viltrum: Scattered mature cities offer Momentum opportunities if Luna''s reinforcement network cannot hold the front.');
